"""Round7: profiling and subtractive time attribution of round6 rawmax8. No new candidate."""
from pathlib import Path
import hashlib
import os
import sys
import torch

HERE=Path(__file__).resolve().parent
BASE=HERE.parent
R6=BASE/"optimization_round6"
R5=BASE/"optimization_round5"
R4=BASE/"optimization_round4"
sys.path.insert(0,str(BASE))
sys.path.insert(0,str(R4))
import gpu_plan as old_plan

# -2 and 0 are the unchanged references; 100+mask are diagnostic builds whose
# partials are garbage by construction (see diag7_kernel.cu header).
NOSTORE,NOEXP,NOROW,NOPV,NOQK,NOGATHER=1,2,4,8,16,32
VARIANTS={"overlap8":-2,"rawmax8":0,"diag0":100,
          "no_store":100+NOSTORE,"no_exp":100+NOEXP,"no_row":100+NOROW,
          "no_pv":100+NOPV,"no_qk":100+NOQK,"no_gather":100+NOGATHER,
          "mma_gather_only":100+NOSTORE+NOROW,"gather_store_only":100+NOROW+NOPV+NOQK}
DIAGNOSTIC=tuple(v for v in VARIANTS.values() if v>=100)
CHUNKS={v:8 for v in VARIANTS.values()}
_OPS=None


def load_extension():
    global _OPS
    if _OPS is None:
        from torch.utils.cpp_extension import load
        build=HERE/"build";build.mkdir(exist_ok=True)
        os.environ.setdefault("MAX_JOBS","2")
        load(name="xomtention_kvopt7",sources=[str(HERE/"wrapper7.cpp"),str(HERE/"diag7_kernel.cu"),
             str(R6/"pipeline6_kernel.cu"),str(R5/"pipeline_kernel.cu"),
             str(R4/"gpu_metadata.cu"),str(BASE/"optimization_round1/combine_warp.cu")],
             build_directory=str(build),extra_cflags=["-O2"],
             extra_cuda_cflags=["-O2","-lineinfo","--ptxas-options=-v","-gencode=arch=compute_100a,code=sm_100a"],
             extra_ldflags=["-lcuda"],is_python_module=False,verbose=True)
        _OPS=torch.ops.xomtention_kvopt7
        old_plan.load_extension=lambda:_OPS
    return _OPS


class Prepared:
    def __init__(self,q,k,v,selected,variant=0,workspace=None):
        if variant not in CHUNKS:raise ValueError("variant")
        if tuple(selected.shape)!=(q.shape[0],k.shape[1],q.shape[2],16):raise ValueError("selected shape")
        if any(t.device!=q.device for t in (k,v,selected)):raise ValueError("device mismatch")
        self.q,self.k,self.v=q,k,v
        self.variant=variant;self.ops=load_extension()
        self.plan=old_plan.GPUPlan(selected,k.shape[2]//128,q.shape[1]//k.shape[1],CHUNKS[variant])
        self.tasks,self.qids,self.ranks=self.plan.tasks,self.plan.qids,self.plan.ranks
        if workspace is None:
            self.partial=torch.empty((*q.shape[:-1],16,128),device=q.device,dtype=torch.float32)
            self.lses=torch.empty((*q.shape[:-1],16),device=q.device,dtype=torch.float32)
            self.out=torch.empty_like(q);self.out_lse=torch.empty(q.shape[:-1],device=q.device,dtype=torch.float32)
        else:
            if workspace.q.shape!=q.shape or workspace.q.device!=q.device:raise ValueError("workspace")
            self.partial,self.lses,self.out,self.out_lse=workspace.partial,workspace.lses,workspace.out,workspace.out_lse

    def poison(self):
        for t in (self.partial,self.lses,self.out,self.out_lse):t.fill_(float("nan"))

    def metadata(self):self.plan.build()
    def main(self):
        self.ops.main_out(self.q,self.k,self.v,self.tasks,self.qids,self.ranks,self.partial,self.lses,self.variant)
    def combine(self):self.ops.combine_out(self.partial,self.lses,self.out,self.out_lse)
    def core(self):self.main();self.combine()
    def run(self):self.metadata();self.core()


def source_evidence():
    paths=[p for p in BASE.rglob("*") if p.is_file() and p.suffix in (".py",".cu",".cuh",".cpp")
           and "results" not in p.parts and "build" not in p.parts]
    keep={"primitives.cuh","metadata.py","reference.py","api.py","validate_gpu.py",
          "optimization_round4/bench_api4.py","optimization_round4/planning.py",
          "optimization_round4/gpu_plan.py","optimization_round4/timing.py",
          "optimization_round4/gpu_metadata.cu","optimization_round5/pipeline_kernel.cu",
          "optimization_round6/pipeline6_kernel.cu","optimization_round1/combine_warp.cu"}
    sources={str(p.relative_to(BASE)):p.read_text() for p in sorted(paths)
             if p.parent==HERE or str(p.relative_to(BASE)) in keep}
    return {"source_text":sources,"source_hashes":{n:hashlib.sha256(s.encode()).hexdigest() for n,s in sources.items()}}

